const MODE = 'write'; // 'dry' | 'write'
let terms = [];
for (const it of $input.all()) { const b = it.json.body !== undefined ? it.json.body : it.json; terms = terms.concat((b && (b.data || b.glossary_terms)) || []); }
if (terms.length < 600) { throw new Error('Glossary fetch looks incomplete: ' + terms.length); }
function iso(x) { return String(x.langIso || '').split('_')[0]; }
function full(t, change) { return (t.translations || []).map(function (x) { const c = change ? change(x) : null; return c || { langId: x.langId, translation: x.translation || '', description: x.description || '' }; }); }
const EDITS = [
  { id: 7173827, from: 'adresa', to: 'poloha', note: 'SK linguist uses "poloha" for a phone\'s location (Zistiť polohu, História polohy); the headline "Location found!" is "Lokalita nájdená!". "Adresa" only for an actual address.' },
  { id: 7431321, from: 'adresa', to: 'lokalita', note: 'SK linguist used "Lokality" for company locations (Mobitrace contact page); use "adresa" only when a street address is shown.' }
];
const report = []; const put = [];
for (const e of EDITS) {
  const t = terms.find(function (x) { return x.id === e.id; });
  const sk = t && (t.translations || []).find(function (x) { return iso(x) === 'sk'; });
  if (!t || !sk) { report.push({ id: e.id, status: 'SKIP: not found' }); continue; }
  if (String(sk.translation).trim() !== e.from) { report.push({ id: e.id, status: 'SKIP: sk is "' + sk.translation + '"' }); continue; }
  put.push({ id: t.id, translations: full(t, function (x) { return x === sk ? { langId: x.langId, translation: e.to, description: e.note } : null; }) });
  report.push({ id: e.id, term: t.term, tags: t.tags, status: 'OK', to: e.to, non_empty_before: (t.translations || []).filter(function (x) { return x.translation; }).length });
}
return [{ json: { mode: MODE, report: report, body: { terms: MODE === 'write' ? put : [] }, create: { terms: [] }, planned_put: put } }];

const b = $('Build glossary update').first().json;
const w = $('Write glossary').first().json;
const c = $input.first().json;
function bd(r) { return r && r.body !== undefined ? r.body : r; }
const wu = (bd(w) && (bd(w).data || [])) || [];
const cu = (bd(c) && (bd(c).data || [])) || [];
return [{ json: { mode: b.mode, report: b.report, put_status: w.statusCode || null, put_errors: bd(w) && bd(w).errors, updated: wu.map(function (t) { return { id: t.id, term: t.term, tags: t.tags, description: t.description, fr: ((t.translations || []).find(function (x) { return x.langIso === 'fr'; }) || {}).translation, filled: (t.translations || []).filter(function (x) { return x.translation; }).length }; }), post_status: c.statusCode || null, post_errors: bd(c) && bd(c).errors, created: cu.map(function (t) { return { id: t.id, term: t.term, tags: t.tags, filled: (t.translations || []).filter(function (x) { return x.translation; }).length, sample: (t.translations || []).filter(function (x) { return ['fr', 'de', 'vi', 'no'].indexOf(x.langIso) !== -1; }).map(function (x) { return x.langIso + ':' + x.translation; }) }; }) } }];

const MODE = 'write'; // 'dry' | 'write'
const plan = $('Translation plan').all().map(function (i) { return i.json; });
const tgt = $('Fetch target key').all().map(function (i) { return i.json; });
function empty(v) { if (v === null || v === undefined) return true; let s = String(v); if (!s.trim()) return true; try { const o = JSON.parse(s); if (o && typeof o === 'object') { return Object.values(o).every(function (x) { return !String(x || '').trim(); }); } } catch (e) {} return false; }
const rows = [];
for (let i = 0; i < plan.length; i++) {
  const p = plan[i]; const r = tgt[i] || {}; const b = r.body !== undefined ? r.body : r; const k = b && b.key;
  const row = { pid: p.pid, key: p.key, iso: p.iso, proposed: p.proposed, write: false };
  const t = k && (k.translations || []).find(function (x) { return x.language_iso === p.iso; });
  if (!t) { row.reason = 'fetch failed / language missing'; rows.push(row); continue; }
  row.current = t.translation; row.last_by = t.modified_by_email;
  if (!empty(t.translation)) { row.reason = 'no longer empty'; rows.push(row); continue; }
  if (MODE !== 'write') { row.reason = 'safe (dry)'; rows.push(row); continue; }
  row.write = true; row.tid = t.translation_id; row.reason = 'write'; rows.push(row);
}
if (MODE !== 'write') { return rows.map(function (r) { return { json: r }; }); }
const w = rows.filter(function (r) { return r.write; });
if (!w.length) { return [{ json: { nothing: true, skipped: rows } }]; }
return w.map(function (r) { return { json: r }; });

const g = $('Guard').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json; });
function norm(v) { if (v && typeof v === 'object') return JSON.stringify(v); try { const o = JSON.parse(v); if (o && typeof o === 'object') return JSON.stringify(o); } catch (e) {} return String(v); }
const out = [];
for (let i = 0; i < g.length; i++) {
  const r = g[i]; const x = res[i] || {}; const b = x.body !== undefined ? x.body : x;
  const now = b && b.translation ? b.translation.translation : null;
  out.push({ key: r.key, iso: r.iso, status: x.statusCode || null, ok: norm(now) === norm(r.proposed), now: now, unverified: b && b.translation ? b.translation.is_unverified : null, err: b && b.error ? JSON.stringify(b.error).slice(0, 200) : '' });
}
return [{ json: { written: out.filter(function (o) { return o.ok; }).length, failed: out.filter(function (o) { return !o.ok; }), rows: out } }];
